const FILE = "${ro}";

async function load() {
  if (LIVE) {
    try {
      const req = new Request(LIVE.url);
      req.headers = LIVE.headers;
      const rows = await req.loadJSON();
      if (rows && rows[0] && rows[0].data) return rows[0].data;
    } catch (e) {}
  }
  try {
    const fm = FileManager.iCloud();
    const path = fm.joinPath(fm.documentsDirectory(), FILE);
    await fm.downloadFileFromiCloud(path);
    return JSON.parse(fm.readString(path));
  } catch (e) {
    return null;
  }
}

function dayKey(d) {
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return d.getFullYear() + "-" + m + "-" + day;
}

function daysUntil(dateKey, todayKey) {
  return Math.round((new Date(dateKey + "T00:00:00") - new Date(todayKey + "T00:00:00")) / 86400000);
}

const ROSE = new Color("#D87A99");
const SOFT = new Color("#9D8189");
const INK = new Color("#2B2D42");

function addText(stack, text, size, weight, color) {
  const t = stack.addText(text);
  t.font = weight === "bold" ? Font.boldSystemFont(size) : Font.systemFont(size);
  t.textColor = color;
  t.lineLimit = 1;
  t.minimumScaleFactor = 0.7;
  return t;
}

const data = await load();
const w = new ListWidget();
w.backgroundColor = new Color("#FFF8F9");
w.setPadding(14, 14, 12, 14);

if (!data) {
  addText(w, "Study Tracker", 14, "bold", INK);
  addText(w, "Nessun dato disponibile. Apri l'app e attiva l'esportazione.", 11, "regular", SOFT).lineLimit = 3;
} else {
  const today = dayKey(new Date());
  const todays = data.tasks.filter((t) => t.date === today);
  const done = todays.filter((t) => t.done).length;
  const left = todays.filter((t) => !t.done);
  const family = config.widgetFamily || "medium";
  const rows = family === "small" ? 1 : family === "large" ? 6 : 3;

  addText(w, "Oggi · " + done + "/" + todays.length + " task", 14, "bold", INK);
  w.addSpacer(4);
  if (todays.length === 0) addText(w, "Nessun task per oggi", 11, "regular", SOFT);
  else if (left.length === 0) addText(w, "Giornata completata 🌸", 11, "bold", ROSE);
  left.slice(0, rows).forEach((t) => {
    addText(w, "○ " + t.name, 11, "regular", INK);
    w.addSpacer(2);
  });
  if (left.length > rows) addText(w, "+" + (left.length - rows) + " altri", 10, "regular", SOFT);

  const exams = (data.exams || [])
    .filter((e) => e.date)
    .map((e) => ({ subject: e.subject, days: daysUntil(e.date, today) }))
    .filter((e) => e.days >= 0)
    .sort((a, b) => a.days - b.days);
  if (exams.length) {
    w.addSpacer();
    exams.slice(0, family === "small" ? 1 : 3).forEach((e) => {
      const row = w.addStack();
      row.centerAlignContent();
      addText(row, e.subject, 10, "regular", SOFT);
      row.addSpacer();
      addText(row, e.days === 0 ? "Oggi!" : e.days + " gg", 11, "bold", ROSE);
    });
  }
}

w.refreshAfterDate = new Date(Date.now() + 15 * 60 * 1000);
if (config.runsInWidget) Script.setWidget(w);
else await w.presentMedium();
Script.complete();
